'use client';

import React, { useRef, useState, useEffect, useCallback } from 'react';

const MAX_RECORDING_SECONDS = 90;

interface RecordingState {
  status: 'idle' | 'requesting' | 'previewing' | 'recording' | 'paused' | 'stopped' | 'error';
  errorMessage: string | null;
  timeRemaining: number;
  recordedTime: number;
  downloadUrl: string | null;
}

export default function VideoRecorder() {
  const videoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const [state, setState] = useState<RecordingState>({
    status: 'idle',
    errorMessage: null,
    timeRemaining: MAX_RECORDING_SECONDS,
    recordedTime: 0,
    downloadUrl: null,
  });

  const clearTimer = useCallback(() => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const stopMediaStream = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  }, []);

  const cleanupRecording = useCallback(() => {
    clearTimer();
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      try {
        mediaRecorderRef.current.stop();
      } catch {
        // ignore
      }
    }
    mediaRecorderRef.current = null;
    chunksRef.current = [];
    if (state.downloadUrl) {
      URL.revokeObjectURL(state.downloadUrl);
    }
  }, [clearTimer, state.downloadUrl]);

  useEffect(() => {
    return () => {
      cleanupRecording();
      stopMediaStream();
      if (state.downloadUrl) {
        URL.revokeObjectURL(state.downloadUrl);
      }
    };
  }, [cleanupRecording, stopMediaStream, state.downloadUrl]);

  const startPreview = async () => {
    setState((prev) => ({
      ...prev,
      status: 'requesting',
      errorMessage: null,
      timeRemaining: MAX_RECORDING_SECONDS,
      recordedTime: 0,
      downloadUrl: null,
    }));

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: true,
      });
      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.muted = true;
        await videoRef.current.play();
      }

      setState((prev) => ({
        ...prev,
        status: 'previewing',
        timeRemaining: MAX_RECORDING_SECONDS,
        recordedTime: 0,
        downloadUrl: null,
      }));
    } catch (err: unknown) {
      const message =
        err instanceof Error ? err.message : 'Unknown error accessing camera/microphone';
      setState((prev) => ({
        ...prev,
        status: 'error',
        errorMessage: message,
      }));
    }
  };

  const startRecording = () => {
    if (!streamRef.current) return;

    const mimeType = getSupportedMimeType();
    const mediaRecorder = new MediaRecorder(streamRef.current, {
      mimeType,
      videoBitsPerSecond: 2500000,
    });

    mediaRecorderRef.current = mediaRecorder;
    chunksRef.current = [];

    mediaRecorder.ondataavailable = (event) => {
      if (event.data && event.data.size > 0) {
        chunksRef.current.push(event.data);
      }
    };

    mediaRecorder.onstop = () => {
      const blob = new Blob(chunksRef.current, { type: mimeType });
      const url = URL.createObjectURL(blob);
      setState((prev) => ({
        ...prev,
        status: 'stopped',
        downloadUrl: url,
      }));
    };

    mediaRecorder.onerror = () => {
      setState((prev) => ({
        ...prev,
        status: 'error',
        errorMessage: 'Recording error occurred.',
      }));
    };

    mediaRecorder.start(1000); // collect every 1s

    setState((prev) => ({
      ...prev,
      status: 'recording',
      timeRemaining: MAX_RECORDING_SECONDS,
      recordedTime: 0,
      downloadUrl: null,
    }));

    timerRef.current = setInterval(() => {
      setState((prev) => {
        const nextRecorded = prev.recordedTime + 1;
        const nextRemaining = Math.max(0, MAX_RECORDING_SECONDS - nextRecorded);

        if (nextRemaining <= 0) {
          // Auto-stop at max
          if (
            mediaRecorderRef.current &&
            mediaRecorderRef.current.state !== 'inactive'
          ) {
            mediaRecorderRef.current.stop();
          }
          clearTimer();
          return {
            ...prev,
            status: 'stopped',
            recordedTime: nextRecorded,
            timeRemaining: 0,
          };
        }

        return {
          ...prev,
          recordedTime: nextRecorded,
          timeRemaining: nextRemaining,
        };
      });
    }, 1000);
  };

  const pauseRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
      mediaRecorderRef.current.pause();
      clearTimer();
      setState((prev) => ({ ...prev, status: 'paused' }));
    }
  };

  const resumeRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'paused') {
      mediaRecorderRef.current.resume();
      timerRef.current = setInterval(() => {
        setState((prev) => {
          const nextRecorded = prev.recordedTime + 1;
          const nextRemaining = Math.max(0, MAX_RECORDING_SECONDS - nextRecorded);

          if (nextRemaining <= 0) {
            if (
              mediaRecorderRef.current &&
              mediaRecorderRef.current.state !== 'inactive'
            ) {
              mediaRecorderRef.current.stop();
            }
            clearTimer();
            return {
              ...prev,
              status: 'stopped',
              recordedTime: nextRecorded,
              timeRemaining: 0,
            };
          }

          return {
            ...prev,
            recordedTime: nextRecorded,
            timeRemaining: nextRemaining,
          };
        });
      }, 1000);
      setState((prev) => ({ ...prev, status: 'recording' }));
    }
  };

  const stopRecording = () => {
    clearTimer();
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
    // onstop handler will transition status to 'stopped'
  };

  const resetAll = () => {
    cleanupRecording();
    stopMediaStream();
    setState({
      status: 'idle',
      errorMessage: null,
      timeRemaining: MAX_RECORDING_SECONDS,
      recordedTime: 0,
      downloadUrl: null,
    });
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const timerColor =
    state.timeRemaining <= 10 ? 'text-[#E8634B]' : 'text-[#5A7D3F]';

  return (
    <div className="w-full max-w-3xl mx-auto">
      <div className="rounded-2xl overflow-hidden border border-[#2A6FBB]/20 shadow-2xl bg-[#1A1D2E]">
        {/* Video area */}
        <div className="relative aspect-video bg-black">
          <video
            ref={videoRef}
            className="w-full h-full object-cover"
            playsInline
            muted
            controls={state.status === 'stopped' && state.downloadUrl ? true : false}
            src={state.status === 'stopped' && state.downloadUrl ? state.downloadUrl : undefined}
          />

          {/* Overlay for idle / requesting */}
          {(state.status === 'idle' || state.status === 'requesting') && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#1A1D2E]/80 text-[#F9F7F2]">
              <div className="w-16 h-16 mb-4 rounded-full border-4 border-[#2A6FBB]/30 border-t-[#2A6FBB] animate-spin" />
              <p className="text-sm font-medium">
                {state.status === 'requesting'
                  ? 'Requesting camera & microphone...'
                  : 'Ready to record'}
              </p>
            </div>
          )}

          {/* Error overlay */}
          {state.status === 'error' && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#1A1D2E]/90 text-[#F9F7F2] px-6 text-center">
              <p className="text-3xl mb-2">⚠️</p>
              <p className="text-sm text-[#E8634B] font-semibold mb-1">Camera Error</p>
              <p className="text-xs text-[#6B7280] max-w-xs">{state.errorMessage}</p>
            </div>
          )}

          {/* Timer badge */}
          {(state.status === 'recording' || state.status === 'paused') && (
            <div className="absolute top-4 right-4 flex items-center gap-2 bg-black/60 backdrop-blur-sm rounded-full px-4 py-2 border border-white/10">
              <span
                className={`w-2 h-2 rounded-full ${
                  state.status === 'recording' ? 'bg-[#E8634B] animate-pulse' : 'bg-[#6B7280]'
                }`}
              />
              <span className={`font-mono text-sm font-bold ${timerColor}`}>
                {formatTime(state.timeRemaining)}
              </span>
            </div>
          )}
        </div>

        {/* Controls */}
        <div className="p-5 flex flex-wrap items-center justify-center gap-3 bg-[#13151f]">
          {state.status === 'idle' && (
            <button
              onClick={startPreview}
              className="flex items-center gap-2 px-6 py-3 rounded-xl bg-[#2A6FBB] text-white font-semibold text-sm hover:bg-[#1f5a9c] transition-colors shadow-lg shadow-[#2A6FBB]/20"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
              Start Recording
            </button>
          )}

          {(state.status === 'previewing') && (
            <>
              <button
                onClick={startRecording}
                className="flex items-center gap-2 px-6 py-3 rounded-xl bg-[#E8634B] text-white font-semibold text-sm hover:bg-[#d9553f] transition-colors shadow-lg shadow-[#E8634B]/20"
              >
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                  <circle cx="12" cy="12" r="10" />
                </svg>
                Record
              </button>
              <button
                onClick={resetAll}
                className="px-5 py-3 rounded-xl border border-[#6B7280]/40 text-[#6B7280] text-sm font-medium hover:text-[#F9F7F2] hover:border-[#F9F7F2]/30 transition-colors"
              >
                Cancel
              </button>
            </>
          )}

          {state.status === 'recording' && (
            <>
              <button
                onClick={pauseRecording}
                className="flex items-center gap-2 px-5 py-3 rounded-xl bg-[#6B7280] text-white font-semibold text-sm hover:bg-[#5a636e] transition-colors"
              >
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                  <rect x="6" y="4" width="4" height="16" />
                  <rect x="14" y="4" width="4" height="16" />
                </svg>
                Pause
              </button>
              <button
                onClick={stopRecording}
                className="flex items-center gap-2 px-5 py-3 rounded-xl bg-[#E8634B] text-white font-semibold text-sm hover:bg-[#d9553f] transition-colors shadow-lg shadow-[#E8634B]/20"
              >
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                  <rect x="4" y="4" width="16" height="16" rx="2" />
                </svg>
                Stop
              </button>
            </>
          )}

          {state.status === 'paused' && (
            <>
              <button
                onClick={resumeRecording}
                className="flex items-center gap-2 px-5 py-3 rounded-xl bg-[#5A7D3F] text-white font-semibold text-sm hover:bg-[#4c6b35] transition-colors"
              >
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                  <polygon points="5,3 19,12 5,21" />
                </svg>
                Resume
              </button>
              <button
                onClick={stopRecording}
                className="flex items-center gap-2 px-5 py-3 rounded-xl bg-[#E8634B] text-white font-semibold text-sm hover:bg-[#d9553f] transition-colors shadow-lg shadow-[#E8634B]/20"
              >
                <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24">
                  <rect x="4" y="4" width="16" height="16" rx="2" />
                </svg>
                Stop
              </button>
            </>
          )}

          {state.status === 'stopped' && (
            <>
              <a
                href={state.downloadUrl || '#'}
                download={`standup-${new Date().toISOString().replace(/[:.]/g, '-')}.webm`}
                className="flex items-center gap-2 px-6 py-3 rounded-xl bg-[#2A6FBB] text-white font-semibold text-sm hover:bg-[#1f5a9c] transition-colors shadow-lg shadow-[#2A6FBB]/20"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                Download Video
              </a>
              <button
                onClick={resetAll}
                className="px-5 py-3 rounded-xl border border-[#6B7280]/40 text-[#6B7280] text-sm font-medium hover:text-[#F9F7F2] hover:border-[#F9F7F2]/30 transition-colors"
              >
                Record Another
              </button>
            </>
          )}

          {state.status === 'error' && (
            <button
              onClick={resetAll}
              className="flex items-center gap-2 px-6 py-3 rounded-xl bg-[#2A6FBB] text-white font-semibold text-sm hover:bg-[#1f5a9c] transition-colors shadow-lg shadow-[#2A6FBB]/20"
            >
              Try Again
            </button>
          )}
        </div>
      </div>

      {/* Helper text */}
      <div className="mt-4 text-center">
        <p className="text-xs text-[#6B7280]">
          Max {MAX_RECORDING_SECONDS}s per standup · Uses your browser&apos;s camera and microphone ·
          All processing happens locally
        </p>
      </div>
    </div>
  );
}

function getSupportedMimeType(): string {
  const types = [
    'video/webm;codecs=vp9,opus',
    'video/webm;codecs=vp8,opus',
    'video/webm;codecs=h264,opus',
    'video/webm',
    'video/mp4',
  ];
  for (const type of types) {
    if (MediaRecorder.isTypeSupported(type)) {
      return type;
    }
  }
  return 'video/webm';
}
